using Godot;
using System;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class ImageWorkspaceOperations
{
    private Settings Descendants(Resource document,GArray ids){var keep=new Settings();foreach(var value in document.Get("layers").AsGodotArray()){var layer=value.As<Resource>();string id=layer.Get("id").AsString();foreach(var selected in ids)if(id==selected.AsString()||_documents.is_descendant(document,id,selected.AsString())){keep[id]=true;break;}}return keep;}
    public void remove_roots(Control owner,GArray ids){var document=Document(owner);var remove=Descendants(document,ids);var layers=document.Get("layers").AsGodotArray();for(int i=layers.Count-1;i>=0;i--)if(remove.ContainsKey(layers[i].As<Resource>().Get("id").AsString()))layers.RemoveAt(i);}
    public void delete_selected(Control owner){var ids=Canvas(owner).Get("selected").AsGodotArray().Duplicate();Action(owner,()=>{remove_roots(owner,ids);Canvas(owner).Get("selected").AsGodotArray().Clear();});}
    public void copy_layers(Control owner){var document=Document(owner);var clipboard=owner.Get("_clipboard").AsGodotArray();clipboard.Clear();var keep=Descendants(document,Canvas(owner).Get("selected").AsGodotArray());foreach(var value in document.Get("layers").AsGodotArray()){var layer=value.As<Resource>();if(keep.ContainsKey(layer.Get("id").AsString()))clipboard.Add(_layers.copy_layer(layer));}owner.Get("status").As<Label>().Text="Copied "+clipboard.Count+" layer(s)";}
    public void paste_layers(Control owner)
    {
        var clipboard=owner.Get("_clipboard").AsGodotArray();if(clipboard.Count==0)return;Action(owner,()=>{var ids=new Settings();foreach(var value in clipboard)ids[value.As<Resource>().Get("id")]=NewId();var selected=Canvas(owner).Get("selected").AsGodotArray();selected.Clear();foreach(var value in clipboard){var original=value.As<Resource>();var layer=_layers.copy_layer(original);layer.Set("id",ids[original.Get("id")]);layer.Set("parent_id",Get(ids,original.Get("parent_id").AsString(),""));if(layer.Get("parent_id").AsString().Length==0){layer.Set("position",layer.Get("position").AsVector2()+new Vector2(20,20));selected.Add(layer.Get("id"));}Document(owner).Get("layers").AsGodotArray().Add(layer);}});selection_changed(owner);
    }
    public void duplicate_layers(Control owner){copy_layers(owner);paste_layers(owner);}
    public void duplicate_for_drag(Control owner){duplicate_layers(owner);var undo=owner.Get("_undo").AsGodotArray();if(undo.Count>0){owner.Set("_before",undo[undo.Count-1]);undo.RemoveAt(undo.Count-1);}}
    public Settings selected_ids_with_relatives(Control owner,GArray ids)
    {
        var document=Document(owner);var keep=Descendants(document,ids);var original=keep.Keys;foreach(var id in original){var layer=_documents.layer_for_id(document,id.AsString());var seen=new HashSet<string>();while(layer!=null&&layer.Get("parent_id").AsString().Length>0){string parent=layer.Get("parent_id").AsString();if(!seen.Add(parent))break;keep[parent]=true;layer=_documents.layer_for_id(document,parent);}}return keep;
    }
    public Resource basic_from_image(Control owner,Image bitmap,string label){var used=bitmap.GetUsedRect();if(used.Size.X<1||used.Size.Y<1)used=new Rect2I(Vector2I.Zero,Vector2I.One);using var cropped=bitmap.GetRegion(used);var layer=_layers.create("basic",Document(owner).Get("canvas_size").AsVector2I());layer.Set("label",label);layer.Set("position",(Vector2)used.Position);layer.Set("dimensions",(Vector2)used.Size);var texture=ImageTexture.CreateFromImage(cropped);layer.Set("texture",texture);layer.Set("paint_base",texture);return layer;}
    public void select_all(Control owner){var document=Document(owner);var selected=Canvas(owner).Get("selected").AsGodotArray();selected.Clear();foreach(var value in _documents.children(document,"")){var layer=value.As<Resource>();if(_documents.can_edit(document,layer))selected.Add(layer.Get("id"));}selection_changed(owner);}
    private static void ReparentTransform(Resource layer,string parent,Transform2D transform){layer.Set("parent_id",parent);layer.Set("rotation",transform.Rotation);var dimensions=layer.Get("dimensions").AsVector2();layer.Set("position",transform*(dimensions*.5f)-dimensions*.5f);}
    public void group_selected(Control owner)
    {
        var document=Document(owner);var selected=Canvas(owner).Get("selected").AsGodotArray();var roots=_documents.selected_roots(document,selected);if(roots.Count==0){add_layer(owner,"group");return;}var group=_layers.create("group",document.Get("canvas_size").AsVector2I());Action(owner,()=>{var transforms=new Settings();foreach(var value in roots){var layer=value.As<Resource>();transforms[layer.Get("id")]=_documents.world_transform(document,layer);}document.Get("layers").AsGodotArray().Add(group);foreach(var value in roots){var layer=value.As<Resource>();ReparentTransform(layer,group.Get("id").AsString(),transforms[layer.Get("id")].AsTransform2D());}selected.Clear();selected.Add(group.Get("id"));});selection_changed(owner);
    }
    public void ungroup_selected(Control owner)
    {
        var document=Document(owner);var selected=Canvas(owner).Get("selected").AsGodotArray();Action(owner,()=>{foreach(var value in _documents.selected_roots(document,selected)){var layer=value.As<Resource>();if(layer.Get("kind").AsString()!="group")continue;string parentId=layer.Get("parent_id").AsString();var parent=_documents.layer_for_id(document,parentId);var inverse=parent!=null?_documents.world_transform(document,parent).AffineInverse():Transform2D.Identity;foreach(var childValue in _documents.children(document,layer.Get("id").AsString())){var child=childValue.As<Resource>();ReparentTransform(child,parentId,inverse*_documents.world_transform(document,child));}document.Get("layers").AsGodotArray().Remove(layer);}selected.Clear();});
    }
    public void parent_selected(Control owner)
    {
        var document=Document(owner);var selected=Canvas(owner).Get("selected").AsGodotArray();var status=owner.Get("status").As<Label>();if(selected.Count<2){status.Text="Select child layers first, then select the parent layer last.";return;}string parentId=selected[selected.Count-1].AsString();var children=new GArray();foreach(var id in selected)if(id.AsString()!=parentId)children.Add(id);foreach(var id in children)if(_documents.is_descendant(document,parentId,id.AsString())){status.Text="That parenting would create a cycle.";return;}Action(owner,()=>{var parent=_documents.layer_for_id(document,parentId);if(parent==null)return;var inverse=_documents.world_transform(document,parent).AffineInverse();foreach(var id in children){var layer=_documents.layer_for_id(document,id.AsString());if(layer!=null)ReparentTransform(layer,parentId,inverse*_documents.world_transform(document,layer));}selected.Clear();selected.Add(parentId);});status.Text="Parented "+children.Count+" layer(s)";
    }
    public void unparent_selected(Control owner){var document=Document(owner);var ids=Canvas(owner).Get("selected").AsGodotArray().Duplicate();Action(owner,()=>{foreach(var id in ids){var layer=_documents.layer_for_id(document,id.AsString());if(layer!=null&&layer.Get("parent_id").AsString().Length>0)ReparentTransform(layer,"",_documents.world_transform(document,layer));}});owner.Get("status").As<Label>().Text="Unparented selected layers";}
    public void reparent_layers(Control owner,GArray ids,string targetId,int section)
    {
        var document=Document(owner);var target=_documents.layer_for_id(document,targetId);if(target==null)return;string parentId=target.Get(section==0?"id":"parent_id").AsString();foreach(var id in ids)if(id.AsString()==parentId||_documents.is_descendant(document,parentId,id.AsString()))return;Action(owner,()=>{var parent=_documents.layer_for_id(document,parentId);var inverse=parent!=null?_documents.world_transform(document,parent).AffineInverse():Transform2D.Identity;var layers=document.Get("layers").AsGodotArray();foreach(var value in _documents.selected_roots(document,ids)){var layer=value.As<Resource>();ReparentTransform(layer,parentId,inverse*_documents.world_transform(document,layer));layers.Remove(layer);int index=layers.IndexOf(target);layers.Insert(Math.Clamp(index+(section<=0?1:0),0,layers.Count),layer);}});
    }
    public void reorder_selected(Control owner,int direction){var document=Document(owner);Action(owner,()=>{var roots=_documents.selected_roots(document,Canvas(owner).Get("selected").AsGodotArray());if(direction>0)roots.Reverse();var layers=document.Get("layers").AsGodotArray();foreach(var value in roots){var layer=value.As<Resource>();var siblings=_documents.children(document,layer.Get("parent_id").AsString());int next=siblings.IndexOf(layer)+direction;if(next<0||next>=siblings.Count)continue;var other=siblings[next];int from=layers.IndexOf(layer),to=layers.IndexOf(other);layers[from]=other;layers[to]=layer;}});}
    public Godot.Collections.Array<Rect2I> crop_spans(Rect2I region,Vector2[] polygon)
    {
        var spans=new Godot.Collections.Array<Rect2I>();if(polygon.Length==0){spans.Add(region);return spans;}for(int y=region.Position.Y;y<region.End.Y;y++){var crossings=new List<double>();double scan=y+.5;for(int i=0;i<polygon.Length;i++){var a=polygon[i];var b=polygon[(i+1)%polygon.Length];if((a.Y<=scan&&b.Y>scan)||(b.Y<=scan&&a.Y>scan))crossings.Add(a.X+(scan-a.Y)*(b.X-a.X)/(b.Y-a.Y));}crossings.Sort();for(int i=0;i+1<crossings.Count;i+=2){int left=Math.Clamp((int)Math.Ceiling(crossings[i]-.5),region.Position.X,region.End.X),right=Math.Clamp((int)Math.Ceiling(crossings[i+1]-.5),region.Position.X,region.End.X);if(right>left)spans.Add(new Rect2I(left,y,right-left,1));}}return spans;
    }
}
